import sys


def find(a, x):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == x:
            return mid
        if a[lo] <= a[mid]:
            if a[lo] <= x < a[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if a[mid] < x <= a[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1


def main():
    tok = sys.stdin.read().split()
    n = int(tok[0])
    a = list(map(int, tok[1:1 + n]))
    q = int(tok[1 + n])
    print('\n'.join(str(find(a, int(x))) for x in tok[2 + n:2 + n + q]))


